variables_css:
:root {
  /* Colors */
  --color-forest-ink: #009959;
  --color-vine: #00b96c;
  --color-neon-sprout: #00ff95;
  --color-ice-blue: #3de1ff;
  --color-obsidian: #000000;
  --color-graphite: #141414;
  --color-carbon: #313232;
  --color-slate: #545454;
  --color-fog: #707070;
  --color-ash: #949494;
  --color-mist: #d6d6d6;
  --color-cloud: #e6e6e6;
  --color-veil: #f0f0f0;
  --color-paper: #fafafa;

  /* Typography — Font Families */
  --font-inter-variable: 'Inter Variable', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-poppins: 'Poppins', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

theme_css:
@theme {
  /* Colors */
  --color-forest-ink: #009959;
  --color-vine: #00b96c;
  --color-neon-sprout: #00ff95;
  --color-ice-blue: #3de1ff;
  --color-obsidian: #000000;
  --color-graphite: #141414;
  --color-carbon: #313232;
  --color-slate: #545454;
  --color-fog: #707070;
  --color-ash: #949494;
  --color-mist: #d6d6d6;
  --color-cloud: #e6e6e6;
  --color-veil: #f0f0f0;
  --color-paper: #fafafa;

  /* Typography */
  --font-inter-variable: 'Inter Variable', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-poppins: 'Poppins', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

